// Keep explicit archival redirects ahead of legacy discovery proxy rules.
// Assets remain at their original paths; only game entry URLs redirect.
export function buildRedirectLines(games, registry) {
  const retired = registry.filter((g) => g.status === "archived" && g.hidden && g.redirectTo);
  const retiredSlugs = new Set();
  const lines = [
    "# AUTO-GENERATED by apps/web/scripts/generate-redirects.mjs",
    "# Sources: games.registry.json (archival entries), games.generated.json (legacy proxies)",
    "# Do not edit by hand — re-run the redirect generator.",
    "",
  ];

  for (const game of retired) {
    const target = registry.find((g) => g.playUrl === game.redirectTo && g.status === "live" && !g.hidden);
    if (!/^[a-z0-9][a-z0-9-]*[a-z0-9]$/.test(game.slug) ||
        game.playUrl !== `/games/${game.slug}/` ||
        !/^\/games\/[a-z0-9][a-z0-9-]*[a-z0-9]\/$/.test(game.redirectTo) ||
        game.redirectTo === game.playUrl || !target) {
      throw new Error(`Invalid archival redirect for ${JSON.stringify(game.slug)}: expected a distinct live local game`);
    }
    retiredSlugs.add(game.slug);
    lines.push(`# Archived entry: ${game.slug} (temporary; preserve assets and historical data)`);
    // Netlify normalizes the trailing slash. Force the redirect over the preserved index.html.
    lines.push(`/games/${game.slug}  ${game.redirectTo}  302!`);
    lines.push(`/games/${game.slug}/index.html  ${game.redirectTo}  302!`);
    lines.push("");
  }

  // An old discovery manifest must not re-enable an archived entry or proxy its assets elsewhere.
  for (const game of games.filter((g) => !retiredSlugs.has(g.slug) && typeof g.proxyTo === "string" && g.proxyTo.length > 0)) {
    const target = game.proxyTo.replace(/\/+$/, "");
    lines.push(`# ${game.slug}`);
    lines.push(`/games/${game.slug}        /games/${game.slug}/        301`);
    lines.push(`/games/${game.slug}/*      ${target}/:splat            200!`);
    lines.push("");
  }
  return lines;
}
